//! Replays the ledger's share of the oracle corpus: every case of a kind this
//! crate answers must get the answer upstream's TypeScript gave, compared as
//! text. The corpus is regenerated by `tools/oracle/refresh.sh`; nothing here
//! needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_audit::oracle::{KINDS, run_case};
use focus_js::json::stringify;
use serde_json::{Value, json};

#[test]
fn every_ledger_case_gets_upstreams_answer() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let mut replayed = std::collections::BTreeMap::new();
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        // Parsed as upstream's driver parses it, so nested objects are in the
        // order a JS object enumerates them.
        let case: Value = focus_js::json::parse(line).unwrap();
        let kind = case["kind"].as_str().unwrap_or_default().to_owned();
        if !KINDS.contains(&kind.as_str()) {
            continue;
        }
        *replayed.entry(kind).or_insert(0) += 1;
        let got = stringify(&json!({ "id": case["id"], "out": run_case(&case) }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    for kind in KINDS {
        assert!(
            replayed.get(kind).copied().unwrap_or(0) >= 100,
            "too few {kind} cases: {replayed:?}"
        );
    }
    assert!(
        differing.is_empty(),
        "{} ledger cases differ from upstream; first:\n{}",
        differing.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn the_corpus_shows_both_accepted_and_refused_entries() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let entries: Vec<&str> = expected
        .lines()
        .filter(|l| l.starts_with("{\"id\":\"audit_entry-"))
        .collect();
    let count = |needle: &str| entries.iter().filter(|l| l.contains(needle)).count();
    assert!(count("\"out\":{\"shard\":\"# Focus Audit Log\\n") > 100);
    assert!(count("Invalid event type: ") > 5);
    assert!(count("Invalid audit field key: ") > 5);
    assert!(count("Reserved field key: Event") > 5);
    assert!(count("<project-dir>") > 5);
}
